const ORDER_STAGES={pending_payment:['pending_proof','cancelled'],pending_proof:['production_ready','cancelled'],production_ready:['in_production','cancelled'],in_production:['quality_check','on_hold'],on_hold:['in_production','cancelled'],quality_check:['ready_to_ship','rework'],rework:['in_production'],ready_to_ship:['shipped'],shipped:['delivered','delivery_exception'],delivery_exception:['shipped','returned'],delivered:['closed','claim_open'],claim_open:['closed','returned'],returned:['closed']};
const SHIPMENT_STAGES={prepared:['labelled','cancelled'],labelled:['collected'],collected:['in_transit'],in_transit:['delivered','exception'],exception:['in_transit','rto','lost']};
const STAFF_ROLES=['CUSTOMER','BUSINESS_ADMIN','SALES','ESTIMATOR','DESIGNER','PLANNER','OPERATOR','QC','STORES','DISPATCH','FINANCE','SUPPORT'];
function formatWhen(value){try{return new Date(value).toLocaleString('en-IN',{dateStyle:'medium',timeStyle:'short'})}catch{return value||'—'}}
function orderOptions(orders,valid){const filtered=orders.filter(o=>valid.includes(o.status));return filtered.map(o=>`<option value="${esc(o.id)}">${esc(o.id.slice(0,16))} · ${esc(o.status.replaceAll('_',' '))}</option>`).join('')||'<option value="">No eligible orders available</option>'}
/** Accessible structured dialog replaces browser prompts for critical business actions. */
function requestForm({title,description='',fields=[],confirm='Confirm',destructive=false}={}){
 const dialog=$('actionDialog'),form=$('actionDialogForm'),holder=$('actionDialogFields');
 $('actionDialogTitle').textContent=title;$('actionDialogDescription').textContent=description;
 $('actionDialogConfirm').textContent=confirm;$('actionDialogConfirm').classList.toggle('button-danger',destructive);
 $('actionDialogError').textContent='';
 holder.innerHTML=fields.map(f=>{
  const id='dialog_'+f.name,type=f.type||'text',required=f.required===false?'':' required',min=f.min??'',max=f.max??'';
  const label=`<label class="dialog-field" for="${id}"><strong>${esc(f.label||f.name)}</strong>${f.hint?`<small>${esc(f.hint)}</small>`:''}`;
  if(type==='select')return label+`<select id="${id}" name="${esc(f.name)}" class="field"${required}>${(f.options||[]).map(o=>`<option value="${esc(o.value)}">${esc(o.label)}</option>`).join('')}</select></label>`;
  if(type==='textarea')return label+`<textarea id="${id}" name="${esc(f.name)}" rows="4" class="field" placeholder="${esc(f.placeholder||'')}" minlength="${f.minlength||1}" maxlength="${f.maxlength||800}"${required}>${esc(f.value||'')}</textarea></label>`;
  return label+`<input id="${id}" name="${esc(f.name)}" class="field" type="${type}" value="${esc(f.value??'')}" placeholder="${esc(f.placeholder||'')}" ${min!==''?`min="${min}"`:''} ${max!==''?`max="${max}"`:''} ${f.step?`step="${f.step}"`:''} ${f.minlength?`minlength="${f.minlength}"`:''} maxlength="${f.maxlength||400}"${required}></label>`;
 }).join('');
 if(typeof dialog.showModal!=='function'){notify('Your browser cannot open secure action forms. Please use a supported browser.',true);return Promise.resolve(null)}
 return new Promise(resolve=>{
  let settled=false;
  const finish=value=>{if(settled)return;settled=true;form.removeEventListener('submit',submit);dialog.removeEventListener('close',close);$('actionDialogClose').removeEventListener('click',cancel);$('actionDialogCancel').removeEventListener('click',cancel);dialog.close();resolve(value)};
  const cancel=()=>finish(null);
  const close=()=>{if(!settled)finish(null)};
  const submit=e=>{e.preventDefault();if(!form.reportValidity())return;const v=Object.fromEntries(new FormData(form));finish(v)};
  form.addEventListener('submit',submit);dialog.addEventListener('close',close,{once:true});$('actionDialogClose').addEventListener('click',cancel);$('actionDialogCancel').addEventListener('click',cancel);dialog.showModal();holder.querySelector('input,select,textarea')?.focus();
 });
}
async function showOrderDetail(id){try{
 const data=await api(`/orders/${encodeURIComponent(id)}`),o=data.order;
 const proofHtml=data.proofs.length?data.proofs.map(p=>`<div class="detail-row"><div><strong>Proof version ${p.version}</strong><small>Submitted ${formatWhen(p.created_at)}</small></div>${status(p.status)}<div class="detail-actions">${p.status==='customer_pending'&&!isStaff()?`<button class="row-action" data-proof-decision="${esc(p.id)}" data-decision="approve">Approve artwork</button><button class="row-action" data-proof-decision="${esc(p.id)}" data-decision="reject">Request changes</button>`:''}</div></div>`).join(''):renderEmpty('Awaiting design proof','A production artwork proof will appear here when the design team submits it.');
 const paymentsHtml=data.payments.length?data.payments.map(pay=>`<div class="detail-row"><div><strong>${INR(pay.amount_minor)}</strong><small>${esc(pay.id.slice(0,20))} · ${formatWhen(pay.created_at)}</small></div>${status(pay.status)}${pay.status==='captured'?`<button class="row-action" data-refund-request="${esc(pay.id)}" data-refund-max="${pay.amount_minor}">Request refund</button>`:''}</div>`).join(''):renderEmpty('No payments confirmed','Payments will appear here only after verification by the provider.');
 const shippingHtml=data.shipments.length?data.shipments.map(sh=>`<div class="detail-row"><div><strong>${esc(sh.carrier)}</strong><small>Waybill ${esc(sh.tracking_number)}</small></div>${status(sh.status)}<div class="detail-actions"><button class="row-action" data-track="${esc(sh.id)}">Tracking history</button>${isStaff()&&SHIPMENT_STAGES[sh.status]?.length?`<button class="row-action" data-shipment-update="${esc(sh.id)}" data-shipment-status="${esc(sh.status)}">Update status</button>`:''}</div></div>`).join(''):renderEmpty('Not dispatched yet','A tracking reference will appear after the dispatch team prepares the shipment.');
 $('orderDetails').innerHTML=`<section class="detail-panel" tabindex="-1"><div class="detail-header"><div><span class="content-eyebrow">ORDER DETAIL / ${esc(o.id.slice(0,16))}</span><h4>Production & delivery journey</h4><p>${esc(o.address||'Delivery address to be confirmed')}</p></div><div>${status(o.status)}<strong class="order-value">${INR(o.total_minor)}</strong></div></div><div class="journey-steps">${['pending_payment','pending_proof','production_ready','in_production','quality_check','ready_to_ship','shipped','delivered'].map((step,index)=>{const current=['pending_payment','pending_proof','production_ready','in_production','quality_check','ready_to_ship','shipped','delivered'].indexOf(o.status);return `<div class="journey-step ${index<=current?'reached':''}"><span>${index+1}</span><small>${esc(step.replaceAll('_',' '))}</small></div>`}).join('')}</div><div class="detail-columns"><div class="detail-block"><h5>Artwork approvals</h5>${proofHtml}</div><div class="detail-block"><h5>Payments & refund requests</h5>${paymentsHtml}${o.status==='pending_payment'&&!state.paymentsEnabled?'<div class="soft-alert">Online payment is not configured. No charge will be made until the merchant enables and verifies Razorpay.</div>':''}${isStaff()&&state.uatEnabled&&roleName()==='SUPER_ADMIN'&&o.status==='pending_payment'?`<button class="row-action" data-demo-capture="${esc(o.id)}" data-demo-total="${o.total_minor}">Record simulated UAT advance</button><div class="uat-warning">UAT ONLY · Does not charge money.</div>`:''}</div><div class="detail-block span-two"><h5>Shipping & delivery</h5>${shippingHtml}<div id="trackingHistory"></div></div></div></section>`;
 $('orderDetails').querySelector('.detail-panel')?.focus({preventScroll:true});
 }catch(e){notify(e.message,true)}
}
async function showShipmentHistory(id){try{const r=await api(`/shipments/${encodeURIComponent(id)}/track`);const history=$('trackingHistory');if(!history)return;history.innerHTML=`<div class="tracking-timeline"><h5>Tracking history · ${esc(r.shipment.carrier)}</h5>${r.events.length?r.events.map(ev=>`<div class="tracking-event"><i aria-hidden="true"></i><div><strong>${esc(ev.status.replaceAll('_',' '))}</strong><span>${formatWhen(ev.at)}${ev.location?' · '+esc(ev.location):''}</span><p>${esc(ev.notes||'')}</p></div></div>`).join(''):'<p>No events have been recorded yet. Tracking events are updated by the dispatch team until a courier integration is configured.'}</div>`;history.scrollIntoView({behavior:'smooth',block:'nearest'});}catch(e){notify(e.message,true)}}
async function clickHandler(e){const b=e.target.closest('[data-category],[data-tab],[data-scroll],[data-kit],[data-finalize],[data-accept],[data-order],[data-detail],[data-transition],[data-proof],[data-role-user],[data-refund-approve],[data-refund-reject],[data-refund-submit],[data-refund-request],[data-proof-decision],[data-track],[data-shipment-update],[data-demo-capture]');if(!b)return;
 if(b.dataset.category)return chooseCategory(b.dataset.category);
 if(b.dataset.scroll)return $(b.dataset.scroll)?.scrollIntoView({behavior:'smooth'});
 if(b.dataset.kit)return chooseCategory(b.dataset.kit);
 if(b.dataset.tab)return displayTab(b.dataset.tab).catch(x=>notify(x.message,true));
 if(b.dataset.finalize){const values=await requestForm({title:'Issue a firm quotation',description:'Confirm material, print process, margins, taxes and freight before offering a binding price.',confirm:'Approve firm quote',fields:[{name:'amount',label:'Firm total (including GST) · ₹',type:'number',value:(Number(b.dataset.amount)/100).toFixed(2),min:1,step:'.01',max:10000000},{name:'notes',label:'Technical & commercial verification notes',type:'textarea',minlength:15,maxlength:800,placeholder:'Material grade, print method, die, proof, logistics and profitability checks'}]});if(!values)return;return action(`/quotes/${b.dataset.finalize}/firm`,{firmTotalMinor:Math.round(Number(values.amount)*100),reviewNotes:values.notes},'POST','Firm quotation approved and made available to the customer.');}
 if(b.dataset.accept){const values=await requestForm({title:'Accept firm quotation',description:'By accepting, you confirm the approved specification and price. The order will be created next.',confirm:'Accept quotation',fields:[]});if(!values)return;return action(`/quotes/${b.dataset.accept}/accept`,{},'POST','Quotation accepted. You can now place your order.');}
 if(b.dataset.order){const values=await requestForm({title:'Delivery destination',description:'Enter an accurate delivery address. Multi-destination fulfilment needs sales review before a firm quotation.',confirm:'Place order',fields:[{name:'address',label:'Full delivery address',type:'textarea',minlength:10,maxlength:800,placeholder:'Recipient, building, street, city, state, PIN and phone'}]});if(!values)return;return action('/orders',{quoteId:b.dataset.order,address:values.address},'POST','Order created. Payment and design proof are the next steps.');}
 if(b.dataset.detail)return showOrderDetail(b.dataset.detail);
 if(b.dataset.transition){const options=ORDER_STAGES[b.dataset.current]||[];if(!options.length)return notify('No next step is available from this order stage.',true);const values=await requestForm({title:'Advance order stage',description:'Status changes are recorded in the audit trail. Proof approval and captured advance remain mandatory.',confirm:'Update order stage',fields:[{name:'to',label:'Next stage',type:'select',options:options.map(v=>({value:v,label:v.replaceAll('_',' ')}))},{name:'reason',label:'Reason / operational note',type:'textarea',minlength:8,maxlength:500,placeholder:'Describe the work completed or reason for changing this stage'}]});if(!values)return;return action(`/orders/${b.dataset.transition}/transition`,values,'POST','Order stage updated.');}
 if(b.dataset.proof){const values=await requestForm({title:'Submit artwork proof',description:'This is a versioned proof notice, not a file upload. Do not start production until the customer approves the actual artwork.',confirm:'Send proof for approval',fields:[{name:'notes',label:'Proof details and version reference',type:'textarea',minlength:10,maxlength:900,placeholder:'Revision version, design changes, approval instructions and secure artwork reference'}]});if(!values)return;return action('/proofs',{orderId:b.dataset.proof,notes:values.notes},'POST','Design proof sent for customer approval.');}
 if(b.dataset.proofDecision){const approved=b.dataset.decision==='approve';const values=await requestForm({title:approved?'Approve latest artwork proof':'Request artwork changes',description:approved?'Only approve after reviewing the actual production artwork outside this preview.':'The design team will need to issue a new proof version.',confirm:approved?'I approve the proof':'Request revision',fields:[]});if(!values)return;return action(`/proofs/${b.dataset.proofDecision}/${b.dataset.decision}`,{},'POST',approved?'Artwork approved.':'Proof returned for revision.');}
 if(b.dataset.roleUser){const values=await requestForm({title:'Change account role',description:'Assign only approved non-superadmin roles. All changes are audit logged.',confirm:'Assign role',fields:[{name:'role',label:'Approved role',type:'select',options:STAFF_ROLES.map(v=>({label:v.replaceAll('_',' '),value:v}))}]});if(!values)return;return action(`/admin/users/${b.dataset.roleUser}/role`,values,'PUT','User role updated.');}
 if(b.dataset.refundRequest){const limit=(Number(b.dataset.refundMax)/100).toFixed(2);const values=await requestForm({title:'Request a refund',description:'Refund eligibility, policy deductions and actual payout will be reviewed by finance. Submitting a request does not issue money.',confirm:'Submit refund request',fields:[{name:'amount',label:'Requested refund · ₹',type:'number',step:'.01',min:'.01',max:limit,value:limit},{name:'reason',label:'Reason for refund',type:'textarea',minlength:5,maxlength:800,placeholder:'Describe the issue and the preferred resolution'}]});if(!values)return;return action('/refunds',{paymentId:b.dataset.refundRequest,requestedMinor:Math.round(Number(values.amount)*100),feeMinor:0,reason:values.reason},'POST','Refund request submitted for review.');}
 if(b.dataset.refundApprove||b.dataset.refundReject){const id=b.dataset.refundApprove||b.dataset.refundReject,decision=b.dataset.refundApprove?'approve':'reject';const values=await requestForm({title:`${decision==='approve'?'Approve':'Reject'} refund request`,description:'Verify captured balance, customer terms, deductions, reason and segregation of duties.',confirm:`${decision==='approve'?'Approve':'Reject'} request`,fields:[]});if(!values)return;return action(`/refunds/${id}/${decision}`,{},'POST','Refund review decision saved.');}
 if(b.dataset.refundSubmit){const values=await requestForm({title:'Submit approved refund to gateway',description:'This submits a financial request to the configured payment provider. Confirm the payout amount and independent approval.',confirm:'Submit to gateway',fields:[]});if(!values)return;return action(`/refunds/${b.dataset.refundSubmit}/submit`,{},'POST','Refund was submitted to the gateway.');}
 if(b.dataset.track)return showShipmentHistory(b.dataset.track);
 if(b.dataset.shipmentUpdate){const options=SHIPMENT_STAGES[b.dataset.shipmentStatus]||[];if(!options.length)return notify('This shipment has no available next stage.',true);const values=await requestForm({title:'Record shipment event',description:'Manual status updates are audit logged. Courier events must be verified separately.',confirm:'Record tracking update',fields:[{name:'status',label:'Next delivery status',type:'select',options:options.map(x=>({value:x,label:x.replaceAll('_',' ')}))},{name:'location',label:'Current location',required:false,maxlength:120,placeholder:'City or sorting centre'},{name:'notes',label:'Tracking notes',type:'textarea',required:false,maxlength:400,placeholder:'Pickup, handover, delivery attempt, proof of delivery'}]});if(!values)return;return action(`/shipments/${b.dataset.shipmentUpdate}/events`,values,'POST','Shipment tracking updated.');}
 if(b.dataset.demoCapture){const values=await requestForm({title:'Record simulated UAT advance',description:'TEST DATA ONLY. Available to Super Admin outside production with UAT_DEMO_ENABLED=true. No payment is charged.',confirm:'Record test advance',fields:[{name:'amount',label:'Test amount · ₹',type:'number',min:(Math.ceil(Number(b.dataset.demoTotal)/2)/100).toFixed(2),max:(Number(b.dataset.demoTotal)/100).toFixed(2),step:'.01',value:(Math.ceil(Number(b.dataset.demoTotal)/2)/100).toFixed(2)}]});if(!values)return;return action('/admin/uat/capture-payment',{orderId:b.dataset.demoCapture,amountMinor:Math.round(Number(values.amount)*100)},'POST','Simulated UAT payment recorded. No money was charged.');}
}
async function submitHandler(e){const id=e.target.id;if(!['jobForm','shipmentForm','inventoryForm','roleForm'].includes(id))return;e.preventDefault();const d=Object.fromEntries(new FormData(e.target));if(id==='jobForm')return action('/admin/work-orders',d);if(id==='shipmentForm')return action('/shipments',d);if(id==='inventoryForm')return action('/admin/inventory',d);if(id==='roleForm')return action('/admin/roles',{code:d.code.trim().toUpperCase(),name:d.name,permissions:{[d.resource]:[d.action]}});}
function applyRotation(){const r=state.rotation;$('productCube').style.transform=`rotateX(${r.x}deg) rotateY(${r.y}deg)`;}
function initRotation(){let down=false,px=0,py=0;const scene=$('cubeScene');scene.addEventListener('pointerdown',e=>{down=true;px=e.clientX;py=e.clientY;scene.setPointerCapture(e.pointerId);});scene.addEventListener('pointermove',e=>{if(!down)return;state.rotation.y+=(e.clientX-px)*.5;state.rotation.x=Math.max(-85,Math.min(85,state.rotation.x-(e.clientY-py)*.4));px=e.clientX;py=e.clientY;applyRotation();});scene.addEventListener('pointerup',()=>down=false);scene.addEventListener('lostpointercapture',()=>down=false);
 for(const [id,x,y] of [['viewFront',0,0],['viewAngle',-22,-29],['viewTop',-80,0]])$(id).onclick=()=>{state.rotation={x,y};applyRotation();document.querySelectorAll('.view-buttons button').forEach(n=>n.classList.toggle('view-active',n.id===id));};}
async function init(){try{const h=await api('/health');state.uatEnabled=!!h.uatDemoEnabled;state.paymentsEnabled=!!h.paymentsEnabled}catch{}document.querySelectorAll('[data-scroll],[data-kit]').forEach(()=>{});$('year').textContent=new Date().getFullYear();$('accountButton').addEventListener('click',async()=>{if(state.user){try{await api('/auth/logout',{method:'POST',body:{}});state.user=null;state.csrf=null;state.workspaceInitialized=false;updateAccount();loadWorkspace();notify('Signed out.');}catch(e){notify(e.message,true)}}else showAuth();});$('closeAuth').onclick=()=>$('authModal').hidden=true;$('authModal').addEventListener('click',e=>{if(e.target===$('authModal'))$('authModal').hidden=true;});$('authSwitch').onclick=()=>{state.authMode=state.authMode==='login'?'register':'login';updateAuthView();};$('authForm').addEventListener('submit',loginOrRegister);$('saveQuoteButton').onclick=saveQuote;$('customRfq').onclick=()=>chooseCategory('custom');$('menuToggle').onclick=()=>{const open=document.querySelector('.nav').classList.toggle('menu-open');$('menuToggle').setAttribute('aria-expanded',String(open));};document.querySelectorAll('.nav a').forEach(a=>a.addEventListener('click',()=>{document.querySelector('.nav').classList.remove('menu-open');$('menuToggle').setAttribute('aria-expanded','false')}));$('workspaceShell').addEventListener('click',e=>{if(e.target.id==='workspaceSignIn')showAuth();});document.addEventListener('click',clickHandler);document.addEventListener('submit',submitHandler);
 for(const id of ['productSelect','materialSelect','finishSelect','sidesSelect','stateSelect','rushInput','shipInput'])$(id).addEventListener('change',id==='productSelect'?()=>chooseCategory($('productSelect').value,false):requestEstimate);
 for(const id of ['quantityInput','lengthInput','widthInput','heightInput','designNotes'])$(id).addEventListener('input',debounce(requestEstimate));
 $('qtyMinus').onclick=()=>{$('quantityInput').value=Math.max(1,Number($('quantityInput').value)-1);requestEstimate()};$('qtyPlus').onclick=()=>{$('quantityInput').value=Math.min(100000,Number($('quantityInput').value)+1);requestEstimate()};
 document.querySelectorAll('.swatch').forEach(b=>b.addEventListener('click',()=>{state.boxColor=b.dataset.color;document.documentElement.style.setProperty('--box-color',state.boxColor);document.querySelectorAll('.swatch').forEach(s=>s.classList.toggle('selected',s===b));$('swatchName').textContent=b.getAttribute('aria-label');}));
 $('logoUpload').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;if(file.size>2_000_000||!['image/png','image/jpeg'].includes(file.type))return notify('Preview logos must be PNG/JPEG under 2 MB. Production uploads require a secure artwork service.',true);const reader=new FileReader();reader.onload=()=>{$('previewBrand').replaceChildren();const image=document.createElement('img');image.src=reader.result;image.alt='Uploaded logo concept';$('previewBrand').append(image);notify('Logo preview updated locally. Upload to a secure proof workflow before ordering.');};reader.readAsDataURL(file);});
 $('categorySearch').addEventListener('input',debounce(categoryCards));document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{state.filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('active',x===b));categoryCards();}));initRotation();
 try{state.catalog=await api('/catalog');fillSelect($('productSelect'),state.catalog.categories);kitContent();categoryCards();chooseCategory('welcome-kit',false);}catch(e){notify('Cannot load catalog. Start the DesignPro API server.',true);$('categoryGrid').innerHTML=renderEmpty('Catalog unavailable','Start the local API or check the server status.');}
 await initSession();}
init();
